PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE automations (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  slug TEXT NOT NULL UNIQUE,
  title TEXT NOT NULL,
  description TEXT NOT NULL,
  category TEXT,
  level TEXT NOT NULL,
  file_type TEXT NOT NULL,
  platform TEXT NOT NULL,
  requirements TEXT NOT NULL,
  code TEXT,
  download_url TEXT,
  video_url TEXT,
  views INTEGER NOT NULL DEFAULT 0,
  downloads INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
INSERT INTO "automations" ("id","slug","title","description","category","level","file_type","platform","requirements","code","download_url","video_url","views","downloads","created_at") VALUES(1,'eteindre-pc','Éteindre le PC en un clic','Un fichier qui affiche en un clic l''adresse IP de ton PC. Il distingue la connexion principale (celle qui va sur Internet, avec l''adresse de ta box) des autres cartes réseau, souvent virtuelles (VirtualBox, VPN...), pour que tu saches laquelle utiliser. Il ne modifie rien sur ton ordinateur, il affiche seulement des informations.','Système','Débutant','bat','Windows','Aucun',replace(replace('@echo off\r\ntitle Adresse IP de ton PC\r\n\r\nREM ====================================================================\r\nREM  AFFICHER L''ADRESSE IP DE TON PC\r\nREM --------------------------------------------------------------------\r\nREM  Ce script ne modifie RIEN sur ton ordinateur.\r\nREM  Il lit seulement la configuration reseau et l''affiche a l''ecran.\r\nREM  Il fonctionne sur Windows 10 et 11 (PowerShell est deja inclus).\r\nREM ====================================================================\r\n\r\necho ============================================================\r\necho   ADRESSE IP DE TON PC\r\necho ============================================================\r\necho.\r\n\r\nREM --------------------------------------------------------------------\r\nREM  PARTIE 1 : la connexion qui te relie vraiment a Internet\r\nREM\r\nREM  On garde uniquement les cartes reseau qui possedent une\r\nREM  "passerelle par defaut". La passerelle, c''est ta box ou ton\r\nREM  routeur : une carte qui en a une est donc bien connectee.\r\nREM  On affiche trois informations : le nom de la connexion\r\nREM  (Wi-Fi ou Ethernet), l''adresse IP de ton PC, et l''adresse de\r\nREM  la box.\r\nREM --------------------------------------------------------------------\r\necho [1] CONNEXION PRINCIPALE (celle qui va sur Internet)\r\necho.\r\npowershell -NoProfile -Command "$c = Get-NetIPConfiguration | Where-Object { $_.IPv4DefaultGateway }; if ($c) { $c | ForEach-Object { Write-Host (''  Connexion      : '' + $_.InterfaceAlias); Write-Host (''  Adresse IP     : '' + $_.IPv4Address.IPAddress); Write-Host (''  Box / routeur  : '' + $_.IPv4DefaultGateway.NextHop); Write-Host '''' } } else { Write-Host ''  Aucune connexion a Internet detectee.'' }"\r\necho   C''est cette adresse qu''il faut utiliser, par exemple pour\r\necho   joindre ton PC depuis ton telephone sur le meme Wi-Fi.\r\necho.\r\n\r\nREM --------------------------------------------------------------------\r\nREM  PARTIE 2 : les autres cartes reseau\r\nREM\r\nREM  Ici on affiche les cartes qui ont une adresse IP mais PAS de\r\nREM  passerelle. Elles ne menent pas a Internet. Ce sont en general\r\nREM  des reseaux virtuels crees par VirtualBox, VMware, WSL ou un VPN.\r\nREM --------------------------------------------------------------------\r\necho ------------------------------------------------------------\r\necho [2] AUTRES CARTES RESEAU (sans acces a Internet)\r\necho.\r\npowershell -NoProfile -Command "$o = Get-NetIPConfiguration | Where-Object { $_.IPv4Address -and -not $_.IPv4DefaultGateway }; if ($o) { $o | ForEach-Object { Write-Host (''  Carte          : '' + $_.InterfaceAlias); Write-Host (''  Adresse IP     : '' + $_.IPv4Address.IPAddress); Write-Host '''' } } else { Write-Host ''  Aucune autre carte active.'' }"\r\necho   Ces cartes sont souvent virtuelles (VirtualBox, VMware, VPN...).\r\necho   Tu peux les ignorer : elles ne servent pas a aller sur Internet.\r\necho.\r\n\r\nREM --------------------------------------------------------------------\r\nREM  EXPLICATION FINALE\r\nREM  Les adresses qui commencent par 192.168, 10. ou 172.16 sont des\r\nREM  adresses PRIVEES : elles ne sont visibles que sur ton reseau.\r\nREM  Ce n''est pas l''adresse que voient les sites web sur Internet.\r\nREM --------------------------------------------------------------------\r\necho ------------------------------------------------------------\r\necho NOTE : ces adresses sont privees, visibles seulement sur ton\r\necho reseau local. Ce n''est pas ton adresse publique sur Internet.\r\necho.\r\npause','\r',char(13)),'\n',char(10)),NULL,NULL,0,0,'2026-10-04 09:17:21');
INSERT INTO "automations" ("id","slug","title","description","category","level","file_type","platform","requirements","code","download_url","video_url","views","downloads","created_at") VALUES(2,'organiser-fichiers','Organiser automatiquement ses fichiers','Trie ton dossier Téléchargements : images, PDF et vidéos sont rangés chacun dans leur dossier.','Fichiers','Débutant','py','Windows, Mac, Linux','Python 3',replace(replace('from pathlib import Path\r\nimport shutil\r\n\r\ndossier = Path.home() / "Downloads"\r\ntypes = {\r\n    "Images": [".jpg", ".png"],\r\n    "PDF": [".pdf"],\r\n    "Videos": [".mp4"],\r\n}\r\n\r\nfor fichier in dossier.iterdir():\r\n    if fichier.is_file():\r\n        for nom, extensions in types.items():\r\n            if fichier.suffix.lower() in extensions:\r\n                cible = dossier / nom\r\n                cible.mkdir(exist_ok=True)\r\n                shutil.move(str(fichier), str(cible / fichier.name))','\r',char(13)),'\n',char(10)),NULL,NULL,0,0,'2026-10-04 09:17:21');
INSERT INTO "automations" ("id","slug","title","description","category","level","file_type","platform","requirements","code","download_url","video_url","views","downloads","created_at") VALUES(3,'afficher-ip','Afficher l''adresse IP de son PC','Un fichier qui affiche en un clic l''adresse IP de ton PC. Il distingue la connexion principale (celle qui va sur Internet, avec l''adresse de ta box) des autres cartes réseau, souvent virtuelles (VirtualBox, VPN...), pour que tu saches laquelle utiliser. Il ne modifie rien sur ton ordinateur, il affiche seulement des informations.',NULL,'Débutant','bat','Windows','Aucun',replace(replace('@echo off\r\ntitle Adresse IP de ton PC\r\n\r\nREM ====================================================================\r\nREM  AFFICHER L''ADRESSE IP DE TON PC\r\nREM --------------------------------------------------------------------\r\nREM  Ce script ne modifie RIEN sur ton ordinateur.\r\nREM  Il lit seulement la configuration reseau et l''affiche a l''ecran.\r\nREM  Il fonctionne sur Windows 10 et 11 (PowerShell est deja inclus).\r\nREM ====================================================================\r\n\r\necho ============================================================\r\necho   ADRESSE IP DE TON PC\r\necho ============================================================\r\necho.\r\n\r\nREM --------------------------------------------------------------------\r\nREM  PARTIE 1 : la connexion qui te relie vraiment a Internet\r\nREM\r\nREM  On garde uniquement les cartes reseau qui possedent une\r\nREM  "passerelle par defaut". La passerelle, c''est ta box ou ton\r\nREM  routeur : une carte qui en a une est donc bien connectee.\r\nREM  On affiche trois informations : le nom de la connexion\r\nREM  (Wi-Fi ou Ethernet), l''adresse IP de ton PC, et l''adresse de\r\nREM  la box.\r\nREM --------------------------------------------------------------------\r\necho [1] CONNEXION PRINCIPALE (celle qui va sur Internet)\r\necho.\r\npowershell -NoProfile -Command "$c = Get-NetIPConfiguration | Where-Object { $_.IPv4DefaultGateway }; if ($c) { $c | ForEach-Object { Write-Host (''  Connexion      : '' + $_.InterfaceAlias); Write-Host (''  Adresse IP     : '' + $_.IPv4Address.IPAddress); Write-Host (''  Box / routeur  : '' + $_.IPv4DefaultGateway.NextHop); Write-Host '''' } } else { Write-Host ''  Aucune connexion a Internet detectee.'' }"\r\necho   C''est cette adresse qu''il faut utiliser, par exemple pour\r\necho   joindre ton PC depuis ton telephone sur le meme Wi-Fi.\r\necho.\r\n\r\nREM --------------------------------------------------------------------\r\nREM  PARTIE 2 : les autres cartes reseau\r\nREM\r\nREM  Ici on affiche les cartes qui ont une adresse IP mais PAS de\r\nREM  passerelle. Elles ne menent pas a Internet. Ce sont en general\r\nREM  des reseaux virtuels crees par VirtualBox, VMware, WSL ou un VPN.\r\nREM --------------------------------------------------------------------\r\necho ------------------------------------------------------------\r\necho [2] AUTRES CARTES RESEAU (sans acces a Internet)\r\necho.\r\npowershell -NoProfile -Command "$o = Get-NetIPConfiguration | Where-Object { $_.IPv4Address -and -not $_.IPv4DefaultGateway }; if ($o) { $o | ForEach-Object { Write-Host (''  Carte          : '' + $_.InterfaceAlias); Write-Host (''  Adresse IP     : '' + $_.IPv4Address.IPAddress); Write-Host '''' } } else { Write-Host ''  Aucune autre carte active.'' }"\r\necho   Ces cartes sont souvent virtuelles (VirtualBox, VMware, VPN...).\r\necho   Tu peux les ignorer : elles ne servent pas a aller sur Internet.\r\necho.\r\n\r\nREM --------------------------------------------------------------------\r\nREM  EXPLICATION FINALE\r\nREM  Les adresses qui commencent par 192.168, 10. ou 172.16 sont des\r\nREM  adresses PRIVEES : elles ne sont visibles que sur ton reseau.\r\nREM  Ce n''est pas l''adresse que voient les sites web sur Internet.\r\nREM --------------------------------------------------------------------\r\necho ------------------------------------------------------------\r\necho NOTE : ces adresses sont privees, visibles seulement sur ton\r\necho reseau local. Ce n''est pas ton adresse publique sur Internet.\r\necho.\r\npause','\r',char(13)),'\n',char(10)),NULL,NULL,0,0,'2026-10-04 17:46:54');
CREATE TABLE `account` (
	`id` text PRIMARY KEY NOT NULL,
	`account_id` text NOT NULL,
	`provider_id` text NOT NULL,
	`user_id` text NOT NULL,
	`access_token` text,
	`refresh_token` text,
	`id_token` text,
	`access_token_expires_at` integer,
	`refresh_token_expires_at` integer,
	`scope` text,
	`password` text,
	`created_at` integer DEFAULT (cast(unixepoch('subsecond') * 1000 as integer)) NOT NULL,
	`updated_at` integer NOT NULL,
	FOREIGN KEY (`user_id`) REFERENCES `user`(`id`) ON UPDATE no action ON DELETE cascade
);
